import{_ as t,o as d,c as i,a2 as o}from"./chunks/framework.DX07gj3j.js";const m=JSON.parse('{"title":"Checks","description":"What WreckCheck checks before a release and how each finding is classified.","frontmatter":{"title":"Checks","description":"What WreckCheck checks before a release and how each finding is classified."},"headers":[],"relativePath":"checks.md","filePath":"checks.md","lastUpdated":1786688212000}'),c={name:"checks.md"};function r(a,e,n,s,h,l){return d(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="checks" tabindex="-1">Checks <a class="header-anchor" href="#checks" aria-label="Permalink to &quot;Checks&quot;">​</a></h1><p>WreckCheck evaluates six release-risk areas. Checks run concurrently, and one check error does not suppress results from the others.</p><h2 id="secrets" tabindex="-1">Secrets <a class="header-anchor" href="#secrets" aria-label="Permalink to &quot;Secrets&quot;">​</a></h2><p>The secret scanner examines files in the working tree for provider-specific credential shapes. It skips <code>.git</code>, dependencies, common build output directories, coverage, and files larger than 1 MiB. It reports file and line information, but never includes the matched secret value.</p><table tabindex="0"><thead><tr><th>Finds</th><th>Severity</th><th>Finding ID</th></tr></thead><tbody><tr><td>AWS access keys</td><td>critical</td><td><code>security:aws-access-key</code></td></tr><tr><td>GitHub tokens</td><td>critical</td><td><code>security:github-token</code></td></tr><tr><td>Stripe secret keys</td><td>critical</td><td><code>security:stripe-secret-key</code></td></tr><tr><td>OpenAI API keys</td><td>critical</td><td><code>security:openai-api-key</code></td></tr><tr><td>PEM, EC, and OpenSSH private keys</td><td>critical</td><td><code>security:private-key</code></td></tr></tbody></table><p>The scan covers files as they exist now. A credential removed from the working tree but still present in Git history is outside this check’s scope.</p><h2 id="environment-files" tabindex="-1">Environment files <a class="header-anchor" href="#environment-files" aria-label="Permalink to &quot;Environment files&quot;">​</a></h2><p>When a <code>.env</code> file is present, WreckCheck checks Git tracking and ignore rules. If both <code>.env</code> and <code>.env.example</code> exist, it also reports variables documented in the example but missing from the actual environment file.</p><table tabindex="0"><thead><tr><th>Condition</th><th>Severity</th><th>Finding ID</th></tr></thead><tbody><tr><td><code>.env</code> is tracked by Git</td><td>critical</td><td><code>environment:env-tracked</code></td></tr><tr><td><code>.env</code> is not ignored</td><td>high</td><td><code>environment:env-not-ignored</code></td></tr><tr><td><code>.env.example</code> variables are missing from <code>.env</code></td><td>medium</td><td><code>environment:env-mismatch</code></td></tr></tbody></table><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><p>For npm and pnpm projects, WreckCheck delegates vulnerability discovery to the project’s own <code>npm audit --json</code> or <code>pnpm audit --json</code>. npm findings include installed version, fixed version when available, direct/transitive status, and advisory links. Yarn and Bun audit support is not available yet.</p><table tabindex="0"><thead><tr><th>Condition</th><th>Severity</th><th>Finding ID</th></tr></thead><tbody><tr><td>Known dependency vulnerability</td><td>from the audit advisory</td><td><code>dependencies:vulnerability</code></td></tr></tbody></table><h2 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h2><p>Docker checks apply when a root-level <code>Dockerfile</code> exists. WreckCheck parses it once and evaluates the build configuration against several safety rules.</p><table tabindex="0"><thead><tr><th>Condition</th><th>Severity</th><th>Finding ID</th></tr></thead><tbody><tr><td>Hard-coded secret in <code>ENV</code> or <code>ARG</code></td><td>critical</td><td><code>docker:embedded-secret</code></td></tr><tr><td>Sensitive <code>.env</code> or <code>.env.*</code> path included by <code>COPY .</code></td><td>high</td><td><code>docker:missing-ignore-env</code>, <code>docker:missing-ignore-env-wildcard</code></td></tr><tr><td>Missing <code>.dockerignore</code> with <code>COPY .</code></td><td>medium</td><td><code>docker:no-dockerignore</code></td></tr><tr><td>Floating base image or no <code>USER</code> instruction</td><td>medium</td><td><code>docker:floating-base-image</code>, <code>docker:root-user</code></td></tr><tr><td><code>.git</code> not excluded from context</td><td>medium</td><td><code>docker:missing-ignore-git</code></td></tr><tr><td><code>node_modules</code> not excluded from context</td><td>low</td><td><code>docker:missing-ignore-node-modules</code></td></tr></tbody></table><p>A base image is considered floating when it has no tag, uses <code>latest</code>, or uses a partial numeric version such as <code>20</code> or <code>20.1</code>. Exact tags and digest-pinned images are accepted.</p><h2 id="build-configuration" tabindex="-1">Build configuration <a class="header-anchor" href="#build-configuration" aria-label="Permalink to &quot;Build configuration&quot;">​</a></h2><p>For Node.js projects, WreckCheck checks the release scripts declared in <code>package.json</code>.</p><table tabindex="0"><thead><tr><th>Missing script</th><th>Severity</th><th>Finding ID</th></tr></thead><tbody><tr><td><code>build</code></td><td>medium</td><td><code>build:missing-build-script</code></td></tr><tr><td><code>test</code></td><td>medium</td><td><code>build:missing-test-script</code></td></tr><tr><td><code>lint</code></td><td>low</td><td><code>build:missing-lint-script</code></td></tr></tbody></table><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Verification converts a failing or timed-out project command into a high-severity finding. The command result itself is also included in terminal and JSON output.</p><table tabindex="0"><thead><tr><th>Condition</th><th>Severity</th><th>Finding ID</th></tr></thead><tbody><tr><td>A verification command fails</td><td>high</td><td><code>verification:command-failed</code></td></tr><tr><td>A verification command exceeds two minutes</td><td>high</td><td><code>verification:command-timed-out</code></td></tr></tbody></table><p>See <a href="/wreckcheck/usage#verification-behavior">Usage</a> for adapters and execution details.</p>',23)])])}const p=t(c,[["render",r]]);export{m as __pageData,p as default};
